from PIL import Image
im = Image.open('radiograph.jpg')
crops={
 'p1':(540,540,820,860),   # mandibular left posterior roots
 'p2':(600,560,900,900),   # mandibular left premolar roots
 'p3':(1150,560,1450,900), # mandibular right molar roots
 'p4':(520,380,780,650),   # maxillary right molar roots
}
for k,b in crops.items():
    t=im.crop(b); t=t.resize((t.width*4,t.height*4), Image.LANCZOS); t.save(f'/tmp/{k}.png'); print(k,t.size)
""}

